    return count

def count_lines(directory):
    """统计代码行数"""
    total = 0
    extensions = ['.py', '.js', '.ts', '.md', '.json', '.bat', '.sh']
    try:
        for root, dirs, files in os.walk(directory):
            if any(skip in root for skip in ['node_modules', 'venv', '.git', '__pycache__']):
