      "timeout_seconds": 300,
      "conditional": null,
      "validation": {
        "min_papers": 3,
        "output_field": "arxiv_papers"
      }
    },
    {
      "step_id": "D2",
      "name": "联想爆发",
      "description": "基于灵感自由联想，产生尽可能多的想法",
