      "timeout_seconds": 600,
      "conditional": null,
      "validation": {
        "min_ideas": 10
      }
    },
    {
      "step_id": "D3",
      "name": "强制连接",
      "description": "将不相关的想法进行组合，产生新的连接",
      "blocking": false,
      "timeout_seconds": 300,
      "conditional": {
        "run_if_min_ideas": 15,
        "skip_message": "想法数量<15 个，跳过强制连接"
      },
      "validation": {
        "min_combinations": 5
      }
    },
    {
      "step_id": "D4",
      "name": "逆向思考",
      "description": "从反面/对立面重新审视问题",
      "blocking": false,
      "timeout_seconds": 300,
      "conditional": {
        "run_if": "time_remaining_minutes >= 5",
        "skip_message": "剩余时间不足 5 分钟，跳过逆向思考"
      }
    },
    {
      "step_id": "D5",
      "name": "快速记录",
      "description": "整理并记录所有想法到发散池",
      "blocking": true,
      "timeout_seconds": 300,
      "conditional": null,
      "validation": {
        "output_file_required": true
      }
    },
    {
      "step_id": "C1",
      "name": "初步筛选",
      "description": "使用简单标准快速筛选想法",
      "blocking": true,
      "timeout_seconds": 300,
      "conditional": null,
      "validation": {
        "min_shortlist": 5
      }
    },
    {
      "step_id": "C2",
      "name": "轻量验证",
      "description": "快速验证想法的可行性和真实性",
      "blocking": false,
      "timeout_seconds": 300,
      "conditional": {
        "run_if_min_shortlist": 5,
        "skip_message": "入围想法<5 个，跳过轻量验证"
      }
    },
    {
      "step_id": "C3",
      "name": "影响力评估",
      "description": "使用影响力 - 可行性矩阵评估想法",
      "blocking": false,
      "timeout_seconds": 300,
      "conditional": {
        "run_if_min_shortlist": 3,
        "skip_message": "入围想法<3 个，跳过影响力评估"
      },
      "validation": {
        "matrix_required": true
      }
    },
    {
      "step_id": "C4",
      "name": "快速批判",
      "description": "使用轻量批判者进行质量审查",
      "blocking": true,
      "timeout_seconds": 300,
      "conditional": null,
      "validation": {
        "critic_score_min": 60
      }
    },
    {
      "step_id": "C5",
      "name": "行动规划",
      "description": "将高优先级想法转化为可执行任务",
      "blocking": true,
      "timeout_seconds": 300,
      "conditional": null,
      "validation": {
        "min_actions": 3,
        "output_file_required": true
      }
    }
  ],
  "max_iterations": 3,
