        {"human_request": true}
      ]
    },
    "stop_if": {
      "any": [
        {"critic_score": "≥85"},
        {"ideas_count": "≥25"},
        {"time_remaining_minutes": "<10"},
        {"iteration_count": "≥3"}
      ]
    },
    "recommendation_logic": {
      "if_iteration_1_and_score_<60": "继续第 2 轮 (大幅改进)",
